async function api(url, options={}){
  const res=await fetch('/api'+url,{credentials:'same-origin',headers:{'Content-Type':'application/json',...(options.headers||{})},...options,body:options.body&&typeof options.body!=='string'?JSON.stringify(options.body):options.body});
  const json=await res.json().catch(()=>({}));if(!res.ok)throw Error(json.error||`Request failed (${res.status})`);return json;
}
